<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Inventory oversight</h1><p>View tracked quantities and low-stock warnings across vendors of every status. Vendors make their own stock adjustments.</p></div></div>
<div class="kpi-grid"><div class="kpi"><span class="kpi-label">Tracked foods</span><strong class="kpi-value"><?= (int) ($summary['tracked'] ?? 0) ?></strong><span class="kpi-note">Items with inventory records</span></div><div class="kpi"><span class="kpi-label">Low stock</span><strong class="kpi-value"><?= (int) ($summary['low_stock'] ?? 0) ?></strong><span class="kpi-note">At or below the vendor’s threshold</span></div></div>
<form class="filter-bar admin-filter" method="get" action="<?= h(app_url('admin.inventory')) ?>"><input type="hidden" name="r" value="admin.inventory"><div class="form-field search-span"><label for="q">Search food or vendor</label><input id="q" name="q" value="<?= h($query) ?>" maxlength="80" placeholder="Food name or storefront"></div><div class="form-field"><label for="vendor">Vendor</label><select id="vendor" name="vendor"><option value="">All vendors</option><?php foreach ($vendors as $record): ?><option value="<?= (int) $record['id'] ?>"<?= $vendorId === (int) $record['id'] ? ' selected' : '' ?>><?= h($record['name']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="stock">Stock status</label><select id="stock" name="stock"><option value="">All stock</option><option value="LOW"<?= $stockFilter === 'LOW' ? ' selected' : '' ?>>Low stock only</option></select></div><button class="button" type="submit">Apply filters</button></form>
<?php if ($items): ?><div class="table-wrap"><table><thead><tr><th>Food</th><th>Vendor</th><th>On hand</th><th>Low-stock threshold</th><th>Menu status</th><th>Vendor status</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= h($item['food_name']) ?></strong></td><td><?= h($item['vendor_name']) ?></td><td><?= h(number_format((float) $item['quantity'], 2)) ?> <?= h($item['unit']) ?><?= (float) $item['quantity'] <= (float) $item['low_stock_threshold'] ? ' · Low' : '' ?></td><td><?= h(number_format((float) $item['low_stock_threshold'], 2)) ?> <?= h($item['unit']) ?></td><td><?= (int) $item['is_available'] ? 'Listed' : 'Unlisted' ?></td><td><?php $status = $item['vendor_status']; require APP_ROOT . '/views/components/status-badge.php'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php $routeName='admin.inventory'; $perPage=$limit; $queryParams=array_filter(['q'=>$query,'stock'=>$stockFilter,'vendor'=>$vendorId]); require APP_ROOT . '/views/components/pagination.php'; ?><?php else: ?><div class="empty-state"><h2>No inventory records match</h2><p>Try clearing a filter. New food records receive an inventory record when created by a vendor.</p></div><?php endif; ?>
